/// Getter of `[SameObject] readonly attribute DOMImplementation implementation;`.
pub(crate) fn attr_implementation_get<D: Dom, const LO: u16, const HI: u16>(
    scope: &mut v8::PinScope,
    args: v8::FunctionCallbackArguments,
    mut rv: v8::ReturnValue,
) {
    let _prof = rt::prof::enter(scope, "get Document.implementation");
    // SAFETY: this member's template has a receiver signature, which V8 checked before the call.
    let this = unsafe { rt::receiver(&args.this()) };
    if let Some(v) = rt::same_object_get(scope, args.this(), {
        static K: rt::Name = rt::Name::new("Document.implementation");
        &K
    }) {
        rv.set(v);
        return;
    }
    let st = rt::state(scope);
    let dom = st.engine::<D>();
    let v = <D as DocumentImpl>::implementation(dom, this);
    let Some(js) = v.to_js(scope) else { return };
    rt::same_object_set(
        scope,
        args.this(),
        {
            static K: rt::Name = rt::Name::new("Document.implementation");
            &K
        },
        js,
    );
    rv.set(js);
}

